function penalCodeForm(code?:Row){form(code?'Edit fictional penal code':'Create fictional penal code',[{name:'code',label:'Roleplay code',value:code?.code,max:20},{name:'title',label:'Title',value:code?.title,max:100},{name:'classification',label:'Classification',type:'select',options:['infraction','misdemeanor','felony'],value:code?.classification??'infraction'},{name:'fine',label:'Fictional fine amount',type:'number',value:code?.fine??0},{name:'description',label:'Definition — community roleplay policy',type:'textarea',wide:true,value:code?.description,max:1500},{name:'active',label:'Available for new charges',type:'checkbox',required:false,value:code?.active??true}],async d=>{await api('/penal-codes'+(code?'/'+code.id:''),code?'PATCH':'POST',{...d,...(code?{version:code.version}:{})});},'These are fictional community rules. Existing citations retain their original code title and fine even when you edit this catalog.');}
