 box.append(table(['Code','Definition','Class','Fictional fine','Status / actions'],rows.map(c=>{const definition=$('div');definition.append($('strong','',c.title),$('p','muted',c.description));return[$('span','',c.code),definition,badge(c.classification),$('span','',String(c.fine)),toolbar(badge(c.active?'Active':'Inactive'),...(has('management')?[btn('Edit',()=>penalCodeForm(c),'small')]:[]))];})));content.append(box);
