async function showAdmission(known?:Row){socket?.close();socket=undefined;summary={};me=undefined as unknown as Me;try{const state:Row=known??await api<Row>('/cad-access');root.replaceChildren();const body=$('main','login-form');body.append($('h1','','CAD approval required'),$('p','',`Current status: ${String(state.status??'unavailable').replaceAll('_',' ')}. Discord sign-in alone does not grant CAD admission.`));const link=$('a','button','View CAD application and status') as HTMLAnchorElement;link.href=state.applicationUrl;body.append(link);root.append(body);}catch{login();}}
